// Authored learning material aligned to OpenStax A&P 2e, sections 4.1–4.6.
// IDs are explicit so reorganizing lessons does not invalidate saved answers.
const lesson=(id,title,body,cue,trap,facts)=>({id,title,body,cue,trap,facts:facts.map(([id,term,definition])=>({id,term,definition}))});
export const modules=[
{id:'types',section:'4.1',title:'Types of Tissues',short:'The tissue map',intro:'One organ. Four cooperating tissue families.',lessons:[
lesson('families','Four families, different jobs','A tissue is a group of cells and their extracellular products organized for a shared function. Most organs combine several tissue types. Histology studies tissues microscopically; a specimen’s architecture helps explain its job.','Cover · connect · contract · communicate.','An organ is not made of just one tissue family.',[
['epithelium','Epithelial tissue','Closely packed cells that cover surfaces, line cavities and form glands.'],['connective','Connective tissue','Cells within an extracellular matrix that support, bind, protect or transport.'],['muscle','Muscle tissue','Excitable cells specialized to contract and produce movement.'],['nervous','Nervous tissue','Neurons and supporting cells specialized for communication and response.'],['histology','Histology','The microscopic study of tissue structure.']]),
lesson('origins','Three embryonic starting points','Ectoderm, mesoderm and endoderm are embryonic germ layers. Nervous tissue arises primarily from ectoderm, muscle from mesoderm, and epithelial tissues can arise from all three. A germ layer is a developmental origin, not a fifth adult tissue family.','Ecto: outer · meso: middle · endo: inner.','Do not assign all epithelia to a single germ layer.',[
['ectoderm','Ectoderm','The germ layer that gives rise to the epidermis and much of the nervous system.'],['mesoderm','Mesoderm','The germ layer that gives rise to muscle and most connective tissues.'],['endoderm','Endoderm','The germ layer that gives rise to much of the digestive and respiratory epithelial lining.']]),
lesson('membranes','Membranes connect tissues to places','Epithelial membranes combine epithelium with underlying connective tissue. Mucous membranes line passages that open to the outside. Serous membranes line closed ventral cavities and cover organs; their fluid reduces friction. Skin is the cutaneous membrane. Synovial membranes are connective tissue membranes in movable joints.','Mucous: passages · serous: slippery sacs · synovial: joints.','Mucous is an adjective; mucus is the secretion. Not every mucous membrane secretes mucus.',[
['cutaneous','Cutaneous membrane','The skin: an epithelial membrane with epidermis and underlying dermis.'],['mucous','Mucous membrane','An epithelial membrane lining a passage that opens to the exterior, such as the digestive tract.'],['serous','Serous membrane','An epithelial membrane lining a closed ventral cavity and covering its organs, reducing friction.'],['synovial','Synovial membrane','A connective tissue membrane lining the internal surface of a movable joint capsule.']])]},
{id:'epithelial',section:'4.2',title:'Epithelial Tissue',short:'Surfaces & glands',intro:'Read the layers. Read the shape. Predict the job.',lessons:[
lesson('polarity','A sheet with two different sides','The apical surface faces a lumen or the exterior. The basal surface attaches to the basement membrane, including the basal lamina. Epithelium is avascular; nutrients diffuse from underlying connective tissue. Its cells are closely packed and often renew rapidly.','Apical faces the space; basal faces the base.','Avascular does not mean no nutrient supply.',[
['apical','Apical surface','The free epithelial surface facing a lumen or the outside.'],['basal','Basal surface','The epithelial surface attached to the underlying basement membrane.'],['avascular','Avascular','Without blood vessels; epithelium relies on diffusion from adjacent tissue.']]),
lesson('junctions','Seal, anchor or communicate','Tight junctions restrict passage between adjacent cells. Anchoring junctions mechanically attach cells; desmosomes help resist stress. Gap junctions contain channels allowing ions and small molecules to pass between cells. These functions can coexist in one sheet.','Tight seals · anchors hold · gaps talk.','Gap junctions connect cell interiors; they are not open tears between cells.',[
['tight','Tight junction','A junction that restricts movement through the space between neighboring cells.'],['anchoring','Anchoring junction','A junction that mechanically fastens cells to each other or to a substrate.'],['gap','Gap junction','A junction with channels that permit ions and small molecules to pass between neighboring cells.']]),
lesson('classification','Name layers before surface shape','Simple means one layer: every cell contacts the basal lamina. Stratified means multiple layers and is named for the shape of the apical cells. Squamous cells are thin and flat, cuboidal cells are about as tall as wide, and columnar cells are tall. Sectioning angle changes appearances, so use several clues.','Count layers → inspect the top cells.','In stratified epithelium, do not name the tissue from the deepest cells.',[
['simple','Simple epithelium','A single epithelial layer in which every cell contacts the basal lamina.'],['stratified','Stratified epithelium','Multiple epithelial layers, named for the shape of the apical cells.'],['squamous','Squamous','A flattened epithelial cell shape suited to thin surfaces.'],['cuboidal','Cuboidal','An epithelial cell shape approximately as tall as it is wide.'],['columnar','Columnar','An epithelial cell shape taller than it is wide.']]),
lesson('locations','Structure predicts function','Simple squamous surfaces favor diffusion and filtration, as in lung alveoli. Simple cuboidal cells commonly absorb and secrete in kidney tubules. Simple columnar cells line much of the digestive tract. Stratified squamous epithelium protects against abrasion; the epidermis is keratinized, while the esophagus is nonkeratinized.','Thin for exchange; many layers for wear.','Endothelium and mesothelium are specialized simple squamous epithelia, not connective tissue.',[
['endothelium','Endothelium','Simple squamous epithelium lining blood and lymphatic vessels.'],['mesothelium','Mesothelium','Simple squamous epithelium forming the epithelial part of serous membranes.'],['keratinized','Keratinized stratified squamous epithelium','Protective epithelium with a surface layer of dead, keratin-rich cells, as in the epidermis.'],['goblet','Goblet cell','A unicellular exocrine gland that secretes mucin, a component of mucus.'],['microvilli','Microvilli','Apical projections that increase surface area for absorption.'],['cilia','Cilia','Motile surface projections that can move material across an epithelial surface.']]),
lesson('special','Two misleading appearances','Pseudostratified epithelium appears layered because nuclei occur at different heights, but every cell contacts the basal lamina. Not all reach the free surface. Transitional epithelium is stratified and changes its apparent thickness and apical cell shape as urinary organs stretch.','Pseudo: false layers. Transitional: changes with filling.','Stretching does not convert transitional tissue into a different tissue family.',[
['pseudo','Pseudostratified columnar epithelium','A single layer with nuclei at different heights; all cells contact the basal lamina.'],['transitional','Transitional epithelium','Stratified urinary epithelium whose surface cells flatten as the organ distends.']]),
lesson('glands','Where does the product go?','Endocrine glands release hormones into interstitial fluid and then the circulation, without ducts. Exocrine glands deliver products onto a surface or into a lumen, often through ducts. A simple gland has an unbranched duct; a compound gland has branched ducts. Tubular and acinar/alveolar describe the secretory units, not their release mechanism.','Endocrine enters circulation; exocrine exits to a surface.','A branched secretory portion does not necessarily mean a compound duct system.',[
['endocrine','Endocrine gland','A ductless gland that releases hormones into interstitial fluid for transport in blood.'],['exocrine','Exocrine gland','A gland that releases products onto an epithelial surface or into a lumen.'],['simple-gland','Simple gland','An exocrine gland with an unbranched duct.'],['compound','Compound gland','An exocrine gland with a branched duct system.'],['tubular','Tubular gland','A gland with tube-shaped secretory units.'],['acinar','Acinar gland','A gland with rounded sac-like secretory units, also called alveolar units.']]),
lesson('secretion','Three release mechanisms','Merocrine secretion uses exocytosis and leaves the cell intact. Apocrine secretion releases an apical portion with its product. Holocrine secretion destroys the secretory cell; the entire cell contributes to the product and must be replaced. Sebaceous glands are holocrine.','Mero: package · apo: top · holo: whole.','The name of a gland and its secretion mechanism are different classification questions.',[
['merocrine','Merocrine secretion','Release by exocytosis while the secretory cell remains intact.'],['apocrine','Apocrine secretion','Release of the apical portion of a secretory cell with its product.'],['holocrine','Holocrine secretion','Release in which the entire secretory cell breaks down and becomes part of the secretion.']])]},
{id:'connective',section:'4.3',title:'Connective Tissue Supports and Protects',short:'Cells & matrix',intro:'The material between cells is part of the story.',lessons:[
lesson('matrix','Cells plus extracellular material','Connective tissue contains cells embedded in extracellular matrix: fibers plus ground substance. Mesenchyme is an embryonic connective tissue. Fibroblasts build matrix; fibrocytes maintain it. Matrix composition, density and fiber orientation explain differences in strength, elasticity and transport.','Matrix = fibers + ground substance.','Adipose has little matrix; not every connective tissue is mostly visible fibers.',[
['matrix','Extracellular matrix','The noncellular material of connective tissue, including fibers and ground substance.'],['ground','Ground substance','The hydrated nonfibrous material surrounding connective tissue cells and fibers.'],['fibroblast','Fibroblast','An active connective tissue cell that produces fibers and ground substance.'],['fibrocyte','Fibrocyte','A less active connective tissue cell that maintains the extracellular matrix.'],['mesenchyme','Mesenchyme','Embryonic connective tissue with cells capable of differentiating into connective tissue cell types.']]),
lesson('fibers','Three fibers, three useful properties','Collagen fibers resist tensile forces. Elastic fibers stretch and recoil. Reticular fibers form delicate supporting networks. Macrophages remove debris, mast cells release inflammatory mediators, and plasma cells produce antibodies. These defense cells coexist with matrix-producing cells.','Collagen: cable · elastic: spring · reticular: net.','Fiber orientation matters as much as fiber abundance.',[
['collagen','Collagen fibers','Strong matrix fibers that resist pulling forces.'],['elastic','Elastic fibers','Matrix fibers that stretch and return toward their original length.'],['reticular','Reticular fibers','Fine branching fibers that form a supportive network.'],['macrophage','Macrophage','A phagocytic defense cell that engulfs debris and pathogens.'],['mast','Mast cell','A connective tissue immune cell that releases mediators such as histamine.'],['plasma-cell','Plasma cell','An immune cell specialized to secrete antibodies.']]),
lesson('loose','Loose connective tissues','Areolar tissue packs spaces and supports epithelia with a loose arrangement of cells and fibers. Adipose stores energy and cushions; white adipocytes have a large lipid droplet, while brown fat specializes in heat production. Reticular tissue forms a supportive framework in soft organs such as lymph nodes.','Areolar packs · adipose stores · reticular supports.','The clear space in a prepared adipocyte often reflects lipid removed during processing.',[
['areolar','Areolar tissue','Loose connective tissue with varied cells and loosely arranged fibers that packs spaces and supports epithelia.'],['adipose','Adipose tissue','Loose connective tissue dominated by lipid-storing adipocytes, providing energy storage and cushioning.'],['reticular-tissue','Reticular tissue','Loose connective tissue with a fiber network supporting cells in organs such as lymph nodes.'],['brown','Brown adipose tissue','Adipose specialized for heat production, with many mitochondria and multiple lipid droplets.']]),
lesson('dense','Follow the direction of the fibers','Dense regular tissue has largely parallel collagen bundles, matching pulling forces along one principal direction, as in tendons. Dense irregular tissue has interwoven bundles, resisting tension in multiple directions, as in the dermis. Elastic connective tissue supports stretch and recoil.','Regular: ropes in a row. Irregular: woven reinforcement.','A tendon is strong mainly along its fiber direction, not equally in every direction.',[
['regular','Dense regular connective tissue','Densely packed, largely parallel collagen bundles suited to tension along one main direction.'],['irregular','Dense irregular connective tissue','Interwoven collagen bundles suited to tension from multiple directions.'],['elastic-tissue','Elastic connective tissue','Connective tissue rich in elastic fibers, supporting repeated stretch and recoil.']]),
lesson('cartilage','Three kinds of cartilage','Chondrocytes occupy lacunae in a firm hydrated matrix. Hyaline cartilage has a relatively smooth-looking matrix with fine collagen; elastic cartilage has a visible elastic fiber network; fibrocartilage has conspicuous collagen bundles and resists compression. Cartilage is avascular, which contributes to slow repair.','Hyaline: smooth support · elastic: flexible shape · fibro: tough cushion.','A lacuna is the space housing a cell, not the cell itself.',[
['chondrocyte','Chondrocyte','A mature cartilage cell occupying a lacuna.'],['lacuna','Lacuna','A small matrix space that houses a cartilage or bone cell.'],['hyaline','Hyaline cartilage','Cartilage with a relatively smooth-appearing matrix, found at articular surfaces and in tracheal support.'],['elastic-cartilage','Elastic cartilage','Cartilage with abundant elastic fibers, as in the external ear.'],['fibrocartilage','Fibrocartilage','Cartilage with thick collagen bundles suited to compression, as in intervertebral discs.']]),
lesson('bone-blood','Solid and fluid connective tissues','Bone has a mineralized matrix that provides rigid support; osteocytes maintain it. Blood has a liquid matrix, plasma, containing formed elements. Erythrocytes transport respiratory gases, leukocytes defend, and platelets are fragments involved in clotting. Lymph returns excess interstitial fluid toward the blood and supports immune transport.','The matrix can be mineralized or liquid.','Platelets are cell fragments; plasma is the matrix, not a blood cell.',[
['bone','Bone tissue','Connective tissue with a mineralized matrix providing rigid support and protection.'],['osteocyte','Osteocyte','A mature bone cell that maintains surrounding bone matrix.'],['plasma','Plasma','The liquid extracellular matrix of blood.'],['erythrocyte','Erythrocyte','A red blood cell specialized for respiratory gas transport.'],['leukocyte','Leukocyte','A white blood cell involved in immune defense.'],['platelet','Platelet','A blood cell fragment involved in clot formation.'],['lymph','Lymph','Fluid carried in lymphatic vessels, returning excess interstitial fluid and transporting immune cells.']])]},
{id:'muscle',section:'4.4',title:'Muscle Tissue and Motion',short:'Three ways to move',intro:'Striations alone do not identify the muscle.',lessons:[
lesson('compare','Compare shape, nuclei and striations','Skeletal muscle fibers are long cylinders with many peripheral nuclei and visible striations. Cardiac muscle cells branch, have striations and usually a central nucleus, and join at intercalated discs. Smooth muscle cells are spindle-shaped with one central nucleus and no visible striations.','Skeletal: cylinders · cardiac: branches · smooth: spindles.','Both skeletal and cardiac muscle are striated.',[
['skeletal','Skeletal muscle','Striated muscle with long cylindrical fibers and multiple peripheral nuclei.'],['cardiac','Cardiac muscle','Striated, branching muscle with central nuclei and intercalated discs.'],['smooth','Smooth muscle','Nonstriated muscle with spindle-shaped cells and single central nuclei.'],['discs','Intercalated discs','Specialized connections between cardiac muscle cells providing mechanical and electrical coupling.']]),
lesson('function','Connect appearance with control','Skeletal muscle moves the skeleton and supports posture, usually under voluntary control. Cardiac muscle pumps blood in the heart and is involuntary. Smooth muscle moves material through hollow organs and adjusts tube diameter; it is involuntary. Excitability and contractility support all three.','Heart pumps; hollow organs propel; skeletal muscles pull.','Voluntary is a useful classification, not a claim that every skeletal contraction is consciously chosen.',[
['excitability','Excitability','The ability of a cell to respond to a stimulus with an electrical change.'],['contractility','Contractility','The ability of muscle tissue to shorten or generate tension.'],['voluntary','Voluntary control','Control associated with consciously initiated skeletal muscle movement.'],['involuntary','Involuntary control','Control of cardiac and smooth muscle without conscious initiation.']])]},
{id:'nervous',section:'4.5',title:'Nervous Tissue Mediates Perception and Response',short:'Signals & support',intro:'Trace the message, then meet the support team.',lessons:[
lesson('neuron','A typical information pathway','Dendrites receive inputs; the cell body contains the nucleus and integrates activity. An axon carries action potentials away from the cell body toward other cells. Myelin insulates many axons and supports rapid conduction. The diagram is a simplified typical pathway, not a universal shape for every neuron.','Dendrites receive; axons send away.','A process visible in a micrograph cannot always be identified as axon or dendrite from appearance alone.',[
['dendrites','Dendrites','Branched neuronal processes that usually receive inputs toward the cell body.'],['soma','Cell body','The region of a neuron containing the nucleus and much of its synthetic machinery.'],['axon','Axon','The neuronal process that carries action potentials away from the cell body.'],['myelin','Myelin','An insulating sheath around many axons that supports rapid signal conduction.']]),
lesson('glia','Neurons need a support network','Astrocytes regulate the extracellular environment and support the blood–brain barrier. Oligodendrocytes form myelin in the central nervous system; Schwann cells do so in the peripheral nervous system. Microglia are resident immune cells with macrophage-related origins. Neuroglia do more than hold neurons in place.','Oligodendrocytes: central. Schwann cells: peripheral.','Microglia differ in developmental origin from other glia; they are still classified among the nervous system’s supporting cells.',[
['astrocyte','Astrocyte','A CNS glial cell that regulates the local environment and supports the blood–brain barrier.'],['oligodendrocyte','Oligodendrocyte','A glial cell that forms myelin in the central nervous system.'],['schwann','Schwann cell','A glial cell that forms myelin around peripheral axons.'],['microglia','Microglia','Resident immune cells of the nervous system that remove debris and respond to injury.']])]},
{id:'repair',section:'4.6',title:'Tissue Injury and Aging',short:'Repair & change',intro:'Follow the response from damage to remodeling.',lessons:[
lesson('inflammation','Why injured tissue changes','Inflammation brings redness, heat, swelling and pain. Vasodilation increases local blood flow, while increased vascular permeability allows fluid and proteins into the tissue. Immune cells remove debris and microbes. Clotting helps stop bleeding and provides a temporary framework. Phases overlap in living tissue.','More flow: red and warm. More fluid outside vessels: swelling.','Inflammation can occur without infection.',[
['inflammation','Inflammation','A protective tissue response involving vascular changes and immune cell recruitment after injury.'],['vasodilation','Vasodilation','Widening of blood vessels that increases local blood flow.'],['permeability','Increased vascular permeability','A vascular change allowing more fluid and proteins to leave vessels and enter injured tissue.'],['clot','Clot formation','A process that limits bleeding and provides a temporary framework at an injury.']]),
lesson('healing','Replacement or repair by scar','Regeneration replaces lost cells with the same functional tissue. Fibrosis deposits collagen-rich scar tissue when full regeneration is limited. Fibroblasts lay down collagen during repair, and remodeling changes its organization over time. Tissue type, damage extent and blood supply affect recovery.','Regeneration restores; fibrosis patches.','A scar can restore continuity without restoring every original function.',[
['regeneration','Regeneration','Replacement of damaged cells with the same functional tissue type.'],['fibrosis','Fibrosis','Repair involving deposition of collagen-rich scar tissue.'],['remodeling','Remodeling','Reorganization and maturation of repaired tissue and its extracellular matrix.']]),
lesson('death-aging','Cells die in different ways','Apoptosis is regulated cell death with organized dismantling and removal, usually without widespread inflammation. Necrosis follows severe damage with loss of membrane integrity and inflammation. Aging can reduce renewal and elasticity; atrophy is a decrease in tissue or organ size, often involving smaller cells.','Apoptosis: orderly removal. Necrosis: damaging breakdown.','Aging changes vary among tissues and individuals.',[
['apoptosis','Apoptosis','Regulated cell death with controlled dismantling and removal.'],['necrosis','Necrosis','Cell death from damage with membrane disruption that commonly provokes inflammation.'],['atrophy','Atrophy','A decrease in the size of a tissue or organ, often involving reduced cell size.']]),
lesson('organization','When growth loses its normal organization','Cancer involves abnormal cell growth with the capacity to invade; malignant cells may spread to distant sites by metastasis. Hyperplasia is increased cell number and is not automatically cancer. Histological organization is one source of evidence, but this activity is not a diagnostic tool.','More cells is not the same as invasion.','A teaching image cannot establish a diagnosis or predict an individual outcome.',[
['hyperplasia','Hyperplasia','An increase in the number of cells in a tissue.'],['metastasis','Metastasis','Spread of malignant cells to establish growth at distant sites.'],['carcinoma','Carcinoma','A malignancy arising from epithelial tissue.'],['sarcoma','Sarcoma','A malignancy arising from connective or other mesenchymal tissues.']])]},
];
